    private String airText(String raw){String v=raw==null?"":raw.trim();if(v.isEmpty()||v.equals("null"))return "дата уточняется";try{java.time.LocalDateTime t=java.time.OffsetDateTime.parse(v).atZoneSameInstant(java.time.ZoneId.systemDefault()).toLocalDateTime();String[] m={"янв","фев","мар","апр","мая","июн","июл","авг","сен","окт","ноя","дек"};return String.format(java.util.Locale.ROOT,"%d %s, %02d:%02d",t.getDayOfMonth(),m[Math.max(0,Math.min(11,t.getMonthValue()-1))],t.getHour(),t.getMinute());}catch(Exception ignored){}return v.replace('T',' ');}
